LEGAL_REF_RE = re.compile(r"(?:\u0645\u0627\u062f\u0647|\u062a\u0628\u0635\u0631\u0647|\u0628\u0646\u062f)\s*[\u06f0-\u06f90-9]+(?:\s*[-\u2013]\s*[\u06f0-\u06f90-9]+)?")
MEASURE_RE = re.compile(r"([\u06f0-\u06f90-9]+(?:[.,\u066b][\u06f0-\u06f90-9]+)?)\s*(\u0645\u062a\u0631\u0645\u0631\u0628\u0639|\u0645\u062a\u0631 \u0645\u0631\u0628\u0639|\u0645\u062a\u0631|\u0633\u0627\u0646\u062a\u06cc ?\u0645\u062a\u0631|\u062f\u0631\u0635\u062f|\u0637\u0628\u0642\u0647|\u0631\u06cc\u0627\u0644|\u062a\u0648\u0645\u0627\u0646)")
HEADING_RE = re.compile(r"^(\u0641\u0635\u0644|\u0628\u062e\u0634|\u06af\u0641\u062a\u0627\u0631|\u0645\u0628\u062d\u062b|\u0645\u0627\u062f\u0647|\u062a\u0628\u0635\u0631\u0647|\u067e\u06cc\u0648\u0633\u062a|\u0636\u0645\u06cc\u0645\u0647)\b")

def classify(text: str, mapping: dict[str, list[str]]) -> list[tuple[str, float]]:
    low = text.lower()
    scores = []
    for label, keys in mapping.items():
        hits = sum(low.count(k) for k in keys)
        if hits:
            scores.append((label, min(.99, .55 + .08 * hits)))
    return sorted(scores, key=lambda x: x[1], reverse=True)

def legal_refs(text: str) -> list[str]:
    return list(dict.fromkeys(m.group(0) for m in LEGAL_REF_RE.finditer(text)))[:30]

def measurements(text: str):
    return [(m.group(1), m.group(2), m.start(), m.end()) for m in MEASURE_RE.finditer(text)][:50]
